def cantor_pairing(x, y):
    """Calculates the Cantor pairing function C(x, y)."""
    S = x + y
    return S * (S + 1) // 2 + y

M = 100
N_C = 0
for x in range(M):
    for y in range(M):
        value = cantor_pairing(x, y)
        if value % 2 != 0:
            N_C += 1

print(f"N for Cantor function C: {N_C}")
